export function toPay(e){if(wx.canIUse("requestPayment")){const n={timeStamp:e.timeStamp,nonceStr:e.nonceStr,signType:e.signType,package:decodeURIComponent(e.package),paySign:decodeURIComponent(e.paySign)};wx.requestPayment(Object.assign(Object.assign({},n),{success(n){"function"==typeof e.success&&e.success(n)},fail(n){"function"==typeof e.fail&&e.fail(n)},complete:function(n){"function"==typeof e.complete&&e.complete(n)}}))}else wx.showModal({content:"你的微信版本过低，请更新至最新版本。",showCancel:!1,success(e){wx.navigateBack()}})}